  "Transform cancelled (right-click).": { ca: "Transformació cancel·lada (clic dret).", es: "Transformación cancelada (clic derecho)." },
  "Transform Type-In works on one selected object.": { ca: "Transform Type-In treballa sobre un sol objecte seleccionat.", es: "Transform Type-In trabaja sobre un solo objeto seleccionado." },
