  "Create tool ended.": { ca: "Eina de creació acabada.", es: "Herramienta de creación terminada." },
  "Creation cancelled.": { ca: "Creació cancel·lada.", es: "Creación cancelada." },
  "Select one object to add a modifier.": { ca: "Selecciona un objecte per afegir-hi un modificador.", es: "Selecciona un objeto para añadirle un modificador." },
  "Modifier removed from the stack.": { ca: "Modificador eliminat de l'stack.", es: "Modificador eliminado del stack." },
  "That name is empty or already used.": { ca: "Aquest nom és buit o ja s'utilitza.", es: "Ese nombre está vacío o ya se usa." },
  "Clone cancelled: nothing changed.": { ca: "Clonatge cancel·lat: no ha canviat res.", es: "Clonación cancelada: no ha cambiado nada." },
  "Select one object for Array.": { ca: "Selecciona un objecte per a Array.", es: "Selecciona un objeto para Array." },
  "Array: more than 400 objects is too many for this lab.": { ca: "Array: més de 400 objectes són massa per a aquest lab.", es: "Array: más de 400 objetos son demasiados para este lab." },
  "Select the objects to group first.": { ca: "Primer selecciona els objectes que vols agrupar.", es: "Primero selecciona los objetos que quieres agrupar." },
  "That name is already used.": { ca: "Aquest nom ja s'utilitza.", es: "Ese nombre ya se usa." },
  "Select a group first.": { ca: "Primer selecciona un grup.", es: "Primero selecciona un grupo." },
  "Select and Scale: 3ds Max cycles Uniform, Non-uniform and Squash when you press R again. This lab uses the gizmo parts instead.": { ca: "Select and Scale: 3ds Max alterna Uniform, Non-uniform i Squash quan tornes a prémer R. Aquest lab fa servir les parts del gizmo.", es: "Select and Scale: 3ds Max alterna Uniform, Non-uniform y Squash cuando vuelves a pulsar R. Este lab usa las partes del gizmo." },
  "Mark found.": { ca: "Marca trobada.", es: "Marca encontrada." },
  "Back to the start. Ctrl+Z undoes it.": { ca: "De tornada a l'inici. Ctrl+Z ho desfà.", es: "De vuelta al inicio. Ctrl+Z lo deshace." },
  "This is one possible solution. Ctrl+Z brings your work back.": { ca: "Aquesta és una solució possible. Ctrl+Z recupera la teva feina.", es: "Esta es una solución posible. Ctrl+Z recupera tu trabajo." },
  "Deleted {n} objects.": { ca: "{n} objectes esborrats.", es: "{n} objetos borrados." },
  "{v} view in the active viewport.": { ca: "Vista {v} al visor actiu.", es: "Vista {v} en el visor activo." },
  "ViewCube: {f}": { ca: "ViewCube: {f}", es: "ViewCube: {f}" },
  "{l}: {n} selected.": { ca: "{l}: {n} seleccionats.", es: "{l}: {n} seleccionados." },
  "{o} is frozen.": { ca: "{o} està congelat.", es: "{o} está congelado." },
  "{t}: not in this lab. Try Box, Sphere, Cylinder, Cone, Torus or Plane.": { ca: "{t}: no és en aquest lab. Prova Box, Sphere, Cylinder, Cone, Torus o Plane.", es: "{t}: no está en este lab. Prueba Box, Sphere, Cylinder, Cone, Torus o Plane." },
  "{t}: drag in a viewport to create it. Right-click or Esc ends the tool.": { ca: "{t}: arrossega en un visor per crear-lo. Clic dret o Esc acaba l'eina.", es: "{t}: arrastra en un visor para crearlo. Clic derecho o Esc termina la herramienta." },
  "{o} created. Drag again to create another one; right-click ends the tool.": { ca: "{o} creat. Torna a arrossegar per crear-ne un altre; clic dret acaba l'eina.", es: "{o} creado. Vuelve a arrastrar para crear otro; clic derecho termina la herramienta." },
  "{m} added to {o}.": { ca: "{m} afegit a {o}.", es: "{m} añadido a {o}." },
  "{o} is unique now: changes no longer reach its instances.": { ca: "{o} ara és únic: els canvis ja no arriben a les seves instàncies.", es: "{o} ahora es único: los cambios ya no llegan a sus instancias." },
  "{n} clones: {m}.": { ca: "{n} clons: {m}.", es: "{n} clones: {m}." },
  "Array: {n} objects in all ({m} new).": { ca: "Array: {n} objectes en total ({m} de nous).", es: "Array: {n} objetos en total ({m} nuevos)." },
  "Group {g}: {n} objects. A click on any of them selects the whole group.": { ca: "Grup {g}: {n} objectes. Un clic a qualsevol d'ells selecciona tot el grup.", es: "Grupo {g}: {n} objetos. Un clic en cualquiera de ellos selecciona todo el grupo." },
  "Ungrouped {g}.": { ca: "{g} desagrupat.", es: "{g} desagrupado." },
  "{g} is open: its parts can be selected one by one. Group › Close when you finish.": { ca: "{g} és obert: les seves peces es poden seleccionar una a una. Group › Close quan acabis.", es: "{g} está abierto: sus piezas se pueden seleccionar una a una. Group › Close cuando termines." },
  "{g} closed.": { ca: "{g} tancat.", es: "{g} cerrado." },
